    icon: <Linkedin className="h-5 w-5 text-[#0A66C2]" />,
    iconBg: "bg-[#0A66C2]/10",
    status: "available",
    category: "Job Boards",
  },
  {
    id: "ziprecruiter",
    name: "ZipRecruiter",
