const CATEGORY_ORDER: IntegrationCategory[] = [
  "Communication",
  "Job Boards",
  "Calendars",
  "Productivity",
  "Developer",
  "ATS & HRIS",
];

// ─── Integration Card ─────────────────────────────────────────────────────────

const IntegrationCard = ({ integration }: { integration: Integration }) => {
  const isConnected = integration.status === "connected";
  const isAvailable = integration.status === "available";
  const isSoon = integration.status === "coming_soon";

  const handleAction = () => {
    if (isConnected) {
      toast.info(`${integration.name} — configuration coming soon`);
    } else if (isAvailable) {
      toast.info(`${integration.name} setup guide coming soon`);
    }
  };

  return (
    <Card className={cn("relative border border-border/60 shadow-sm hover:shadow-md transition-shadow p-5", isSoon && "opacity-60")}>
      {/* Status badge */}
      {isConnected && (
        <Badge className="absolute top-4 right-4 text-[10px] font-semibold bg-emerald-50 text-emerald-700 hover:bg-emerald-50 border border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-400 dark:border-emerald-800">
          Connected
        </Badge>
      )}
      {isAvailable && (
        <Badge variant="outline" className="absolute top-4 right-4 text-[10px] font-semibold bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-800">
          Available
        </Badge>
      )}
      {isSoon && (
        <Badge variant="secondary" className="absolute top-4 right-4 text-[10px] font-semibold">
          Soon
        </Badge>
      )}

      {/* Icon */}
      <div className={cn("h-10 w-10 rounded-xl flex items-center justify-center mb-3.5", integration.iconBg)}>
        {integration.icon}
      </div>

      {/* Text */}
      <p className="text-sm font-semibold text-foreground">{integration.name}</p>
      <p className="text-xs text-muted-foreground mt-1 leading-relaxed">{integration.description}</p>

      {/* Action */}
      {isConnected && (
        <Button variant="ghost" size="sm" className="mt-4 h-8 text-xs w-full text-muted-foreground" onClick={handleAction}>
          Configure
        </Button>
      )}
      {isAvailable && (
        <Button variant="outline" size="sm" className="mt-4 h-8 text-xs w-full" onClick={handleAction}>
          Connect
        </Button>
      )}
    </Card>
  );
};

// ─── Integration Grid (with optional category grouping) ───────────────────────

const IntegrationGrid = ({ items, grouped = false }: { items: Integration[]; grouped?: boolean }) => {
  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 space-y-3">
        <div className="rounded-xl bg-muted/50 p-4">
          <Search className="h-6 w-6 text-muted-foreground/50" />
        </div>
        <p className="text-sm font-medium">No integrations found</p>
        <p className="text-xs text-muted-foreground">Try a different search term</p>
      </div>
    );
  }

  if (!grouped) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {items.map((integ) => (
          <IntegrationCard key={integ.id} integration={integ} />
        ))}
      </div>
    );
  }

  const byCategory = CATEGORY_ORDER.reduce<Record<string, Integration[]>>((acc, cat) => {
    const group = items.filter((i) => i.category === cat);
    if (group.length > 0) acc[cat] = group;
    return acc;
  }, {});

  return (
    <div className="space-y-8">
      {Object.entries(byCategory).map(([category, group]) => (
        <div key={category}>
          <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-3">{category}</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {group.map((integ) => (
              <IntegrationCard key={integ.id} integration={integ} />
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

// ─── API & Webhooks tab — content from ApiDocs ────────────────────────────────

const BASE_URL = "https://zkzontawprihrzpayeam.supabase.co/functions/v1/public-api";

const METHOD_COLORS: Record<string, string> = {
  GET: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400 border-emerald-200/60",
  POST: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 border-blue-200/60",
  DELETE: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 border-red-200/60",
  PATCH: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 border-amber-200/60",
};

function MethodBadge({ method }: { method: string }) {
  return (
    <span className={`inline-block text-[11px] font-bold font-mono px-1.5 py-0.5 rounded border ${METHOD_COLORS[method] ?? "bg-muted text-muted-foreground"}`}>
      {method}
    </span>
  );
}

function CodeBlock({ code, language = "bash" }: { code: string; language?: string }) {
  const handleCopy = () => {
    navigator.clipboard.writeText(code.trim());
    toast.success("Copied to clipboard");
  };
  return (
    <div className="relative rounded-lg bg-zinc-950 dark:bg-zinc-900 border border-border overflow-hidden">
      <div className="flex items-center justify-between px-4 py-2 border-b border-border/40">
        <span className="text-[11px] font-mono text-zinc-400 uppercase tracking-wider">{language}</span>
        <Button variant="ghost" size="sm" className="h-6 w-6 p-0 text-zinc-400 hover:text-zinc-200" onClick={handleCopy}>
          <Copy className="h-3 w-3" />
        </Button>
      </div>
      <pre className="px-4 py-3 text-sm font-mono text-zinc-200 overflow-x-auto leading-relaxed whitespace-pre">
        {code.trim()}
      </pre>
    </div>
  );
}

interface EndpointProps {
  method: string;
  path: string;
  description: string;
  params?: { name: string; type: string; required: boolean; description: string }[];
  responseExample?: string;
  requestExample?: string;
}

function Endpoint({ method, path, description, params, responseExample, requestExample }: EndpointProps) {
  const [open, setOpen] = useState(false);
  return (
    <div className="rounded-lg border border-border overflow-hidden">
      <button
        className="w-full flex items-center gap-3 px-4 py-3 hover:bg-muted/40 transition-colors text-left"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        <MethodBadge method={method} />
        <code className="text-sm font-mono text-foreground flex-1">{path}</code>
        <span className="text-sm text-muted-foreground hidden sm:block">{description}</span>
        <ChevronRight className={`h-4 w-4 text-muted-foreground shrink-0 transition-transform ${open ? "rotate-90" : ""}`} />
      </button>
      {open && (
        <div className="border-t border-border bg-muted/10 px-4 py-4 space-y-4">
          <p className="text-sm text-muted-foreground">{description}</p>
          {params && params.length > 0 && (
            <div>
              <p className="text-xs font-semibold text-foreground uppercase tracking-wider mb-2">Parameters</p>
              <div className="rounded-lg border border-border overflow-hidden">
                <table className="w-full text-sm">
