                  </thead>
                  <tbody className="divide-y divide-border">
                    {params.map((p) => (
                      <tr key={p.name}>
                        <td className="px-3 py-2 font-mono text-xs text-foreground">{p.name}</td>
                        <td className="px-3 py-2 font-mono text-xs text-muted-foreground">{p.type}</td>
                        <td className="px-3 py-2">
