        </CardHeader>
        <CardContent className="space-y-3">
          <CodeBlock code={`Authorization: Bearer rk_live_YOUR_KEY_HERE`} language="http" />
          <div className="rounded-lg bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 px-4 py-3">
            <p className="text-xs text-amber-800 dark:text-amber-200">
              Never expose your API key in client-side code. Always make requests from your backend server or a trusted environment.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Rate Limits */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm font-semibold">Rate Limits</CardTitle>
          <CardDescription>All API keys are subject to the following rate limits.</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-3 gap-4">
            {[
              { label: "Requests", value: "100/min", note: "Per API key" },
              { label: "Jobs created", value: "50/day", note: "Via API" },
              { label: "Candidates", value: "500/req", note: "Per response" },
            ].map((item) => (
              <div key={item.label} className="rounded-lg border border-border bg-muted/30 px-4 py-3 text-center">
                <p className="text-lg font-bold tabular-nums text-foreground">{item.value}</p>
                <p className="text-xs font-medium text-foreground mt-0.5">{item.label}</p>
                <p className="text-[11px] text-muted-foreground">{item.note}</p>
              </div>
            ))}
          </div>
          <p className="text-xs text-muted-foreground mt-3">
            When rate-limited you receive HTTP 429. Retry after the <code className="font-mono">Retry-After</code> header value (seconds).
          </p>
        </CardContent>
      </Card>

      {/* Error Codes */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm font-semibold">Error Codes</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="rounded-lg border border-border overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-muted/50">
                <tr>
                  <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Status</th>
                  <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Code</th>
                  <th className="text-left px-3 py-2 text-xs font-semibold text-muted-foreground">Meaning</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border text-xs">
                {[
                  { status: "400", code: "bad_request", meaning: "Invalid JSON or missing required fields" },
                  { status: "400", code: "validation_error", meaning: "Field validation failed" },
                  { status: "401", code: "unauthorized", meaning: "Missing, invalid, or revoked API key" },
                  { status: "404", code: "not_found", meaning: "Resource not found or access denied" },
                  { status: "405", code: "method_not_allowed", meaning: "HTTP method not supported for this route" },
                  { status: "429", code: "rate_limited", meaning: "Too many requests — slow down" },
                  { status: "500", code: "error", meaning: "Internal server error" },
                ].map((row) => (
                  <tr key={row.code}>
                    <td className="px-3 py-2 font-mono">{row.status}</td>
                    <td className="px-3 py-2 font-mono text-muted-foreground">{row.code}</td>
                    <td className="px-3 py-2 text-muted-foreground">{row.meaning}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Endpoints */}
      <div>
        <h2 className="text-sm font-semibold text-foreground mb-3">Endpoints</h2>
        <div className="space-y-2">
          {ENDPOINTS.map((ep) => (
            <Endpoint key={`${ep.method}-${ep.path}`} {...ep} />
          ))}
        </div>
      </div>

      {/* Quickstart */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <div className="flex items-center gap-2">
            <BookOpen className="h-4 w-4 text-primary" />
            <CardTitle className="text-sm font-semibold">5-Minute Quickstart</CardTitle>
          </div>
          <CardDescription>Get candidate data from Rankora into your app in under 5 minutes.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-5">
          {[
            {
              step: "1",
              title: "Generate an API key",
              description: "Go to the API Keys section above and click \"Generate Key\". Copy the key — it's only shown in full once.",
            },
            {
              step: "2",
              title: "List your jobs",
              description: "Make your first request to verify authentication:",
              code: {
                bash: `curl -X GET "${BASE_URL}/jobs" \\
  -H "Authorization: Bearer rk_live_YOUR_KEY"`,
                javascript: `const res = await fetch("${BASE_URL}/jobs", {
  headers: { "Authorization": "Bearer rk_live_YOUR_KEY" }
});
const { data } = await res.json();
console.log(data); // [{ id, title, status, created_at }]`,
                python: `import requests

response = requests.get(
    "${BASE_URL}/jobs",
    headers={"Authorization": "Bearer rk_live_YOUR_KEY"}
)
jobs = response.json()["data"]
print(jobs)`,
              },
            },
            {
              step: "3",
              title: "Get candidates for a job",
              description: "Pick a job ID from step 2 and fetch its ranked candidates:",
              code: {
                bash: `curl -X GET "${BASE_URL}/jobs/JOB_ID/candidates" \\
  -H "Authorization: Bearer rk_live_YOUR_KEY"`,
                javascript: `const res = await fetch("${BASE_URL}/jobs/JOB_ID/candidates", {
  headers: { "Authorization": "Bearer rk_live_YOUR_KEY" }
});
const { data } = await res.json();
data.forEach(c => console.log(c.candidate_name, c.overall_score));`,
                python: `response = requests.get(
    f"${BASE_URL}/jobs/JOB_ID/candidates",
    headers={"Authorization": "Bearer rk_live_YOUR_KEY"}
)
candidates = response.json()["data"]
for c in candidates:
    print(c["candidate_name"], c["overall_score"])`,
              },
            },
          ].map(({ step, title, description, code }) => (
            <div key={step} className="space-y-3">
              <div className="flex items-start gap-3">
                <span className="h-6 w-6 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">
                  {step}
                </span>
                <div>
                  <h3 className="text-sm font-medium text-foreground">{title}</h3>
                  <p className="text-sm text-muted-foreground mt-0.5">{description}</p>
                </div>
              </div>
              {code && (
                <div className="ml-9">
                  <Tabs defaultValue="bash">
                    <TabsList className="h-7 mb-2">
                      <TabsTrigger value="bash" className="text-xs h-6">cURL</TabsTrigger>
                      <TabsTrigger value="javascript" className="text-xs h-6">JavaScript</TabsTrigger>
                      <TabsTrigger value="python" className="text-xs h-6">Python</TabsTrigger>
                    </TabsList>
                    <TabsContent value="bash"><CodeBlock code={code.bash} language="bash" /></TabsContent>
                    <TabsContent value="javascript"><CodeBlock code={code.javascript} language="javascript" /></TabsContent>
                    <TabsContent value="python"><CodeBlock code={code.python} language="python" /></TabsContent>
                  </Tabs>
                </div>
              )}
            </div>
          ))}
        </CardContent>
      </Card>

      {/* Webhooks */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-2">
          <div className="flex items-center gap-2">
            <Webhook className="h-4 w-4 text-primary" />
            <CardTitle className="text-sm font-semibold">Webhooks</CardTitle>
          </div>
          <CardDescription>
            Receive real-time push notifications when events happen — no polling needed.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          <div>
            <p className="text-xs font-semibold text-foreground uppercase tracking-wider mb-2">Available Events</p>
            <div className="flex flex-wrap gap-1.5">
              {["job.created", "ranking.completed", "candidate.applied", "candidate.rejected", "interview.scheduled"].map((e) => (
                <Badge key={e} variant="secondary" className="font-mono text-[11px]">{e}</Badge>
              ))}
            </div>
          </div>
          <div>
            <p className="text-xs font-semibold text-foreground uppercase tracking-wider mb-2">Payload Example</p>
            <CodeBlock
              code={`{
  "event": "ranking.completed",
  "timestamp": "2026-04-09T10:00:00Z",
  "data": {
    "job_id": "3f8a1c2b-...",
    "job_title": "Senior React Developer",
    "total_candidates": 12,
    "top_score": 87
  }
}`}
              language="json"
            />
          </div>
          <p className="text-xs text-muted-foreground">
            Register webhook URLs in the API Keys section above. All webhooks are signed with HMAC-SHA256 using your webhook secret.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

// ─── Main Page ─────────────────────────────────────────────────────────────────

const Integrations = () => {
  const [search, setSearch] = useState("");

  const filtered = useMemo(() => {
    const q = search.toLowerCase().trim();
    if (!q) return INTEGRATIONS;
    return INTEGRATIONS.filter(
      (i) => i.name.toLowerCase().includes(q) || i.description.toLowerCase().includes(q)
    );
  }, [search]);

  const connectedItems = filtered.filter((i) => i.status === "connected");
  const comingSoonItems = filtered.filter((i) => i.status === "coming_soon");

  return (
    <SidebarLayout>
      <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Page header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-foreground">Integrations</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Connect your favorite tools to streamline your hiring workflow.
          </p>
        </div>

        <Tabs defaultValue="all">
          <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-6">
            <TabsList className="shrink-0">
              <TabsTrigger value="all" className="gap-1.5">All</TabsTrigger>
              <TabsTrigger value="connected" className="gap-1.5">Connected</TabsTrigger>
              <TabsTrigger value="api" className="gap-1.5">
                <Code2 className="h-3.5 w-3.5" />
                API &amp; Webhooks
              </TabsTrigger>
              <TabsTrigger value="coming_soon" className="gap-1.5">Coming Soon</TabsTrigger>
            </TabsList>

            {/* Search — hidden on API tab */}
            <div className="relative flex-1 max-w-xs">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
              <Input
                placeholder="Search integrations..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-8 h-9 text-sm"
              />
            </div>
          </div>

          <TabsContent value="all">
            <IntegrationGrid items={filtered} grouped={!search} />
          </TabsContent>

          <TabsContent value="connected">
            <IntegrationGrid items={connectedItems} />
          </TabsContent>

          <TabsContent value="api">
            <ApiWebhooksTab />
          </TabsContent>

          <TabsContent value="coming_soon">
            <IntegrationGrid items={comingSoonItems} />
          </TabsContent>
        </Tabs>
      </main>
    </SidebarLayout>
  );
};

export default Integrations;

